changeSet.sql:
DO $$
BEGIN
    IF to_regclass('custom_field') IS NULL OR to_regclass('field_form_config') IS NULL THEN
        RETURN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM custom_field WHERE custom_field_id = -327) THEN
        RETURN;
    END IF;

    INSERT INTO custom_field (answer_type, custom_field_id, is_system_field, label, value_binding, field_code)
    SELECT 'SELECT_MULTIPLE_STRATIGRAPHY', v.id, true, v.label, v.binding, v.code
    FROM (VALUES
        (-328, 'recordingunit.field.anteriorRelationships', 'anteriorRelationships', 'SIARU.STRATI.ANTERIOR'),
        (-329, 'recordingunit.field.posteriorRelationships', 'posteriorRelationships', 'SIARU.STRATI.POSTERIOR'),
        (-330, 'recordingunit.field.synchronousRelationships', 'synchronousRelationships', 'SIARU.STRATI.SYNCHRONOUS')
    ) AS v(id, label, binding, code)
    WHERE NOT EXISTS (SELECT 1 FROM custom_field c WHERE c.custom_field_id = v.id);

    INSERT INTO field_form_config (is_active, is_institution_locked, is_mandatory, position, fk_custom_field_id,
                                   fk_form_config_id, rules, width, fk_group_id, units)
    SELECT f.is_active, f.is_institution_locked, f.is_mandatory, f.position, v.id,
           f.fk_form_config_id, f.rules, f.width, f.fk_group_id, f.units
    FROM field_form_config f
    CROSS JOIN (VALUES (-328), (-329), (-330)) AS v(id)
    WHERE f.fk_custom_field_id = -327
      AND NOT EXISTS (SELECT 1 FROM field_form_config n
                      WHERE n.fk_custom_field_id = v.id AND n.fk_form_config_id = f.fk_form_config_id);

    IF to_regclass('field_form_config_concept') IS NOT NULL THEN
        DELETE FROM field_form_config_concept WHERE fk_custom_field_id = -327;
    END IF;
    IF to_regclass('concept_field_state') IS NOT NULL THEN
        DELETE FROM concept_field_state WHERE fk_custom_field_id = -327;
    END IF;
    DELETE FROM field_form_config WHERE fk_custom_field_id = -327;
    DELETE FROM custom_field
    WHERE custom_field_id = -327
      AND NOT EXISTS (SELECT 1 FROM custom_field_answer WHERE fk_custom_field_id = -327);
END
$$;
